/* ── 1. Inject profile photo as base64 ──────────────────── */
    const PHOTO_DATA = '';
    const photoSrc   = 'data:image/jpeg;base64,' + PHOTO_DATA;
    document.getElementById('heroPhoto').src  = photoSrc;
    document.getElementById('aboutPhoto').src = photoSrc;

    /* ── 2. Sticky nav ──────────────────────────────────────── */
    const nav = document.getElementById('nav');
    window.addEventListener('scroll', () => {
      nav.classList.toggle('scrolled', window.scrollY > 40);
    }, { passive: true });

    /* ── 3. Hamburger menu ──────────────────────────────────── */
    const hamburger   = document.getElementById('hamburger');
    const mobileMenu  = document.getElementById('mobileMenu');
    const mobileLinks = document.querySelectorAll('.mobile-link');

    function toggleMenu(open) {
      hamburger.classList.toggle('open', open);
      mobileMenu.classList.toggle('open', open);
      hamburger.setAttribute('aria-expanded', open);
      document.body.style.overflow = open ? 'hidden' : '';
    }
    hamburger.addEventListener('click', () => {
      const isOpen = mobileMenu.classList.contains('open');
      toggleMenu(!isOpen);
    });
    mobileLinks.forEach(link => link.addEventListener('click', () => toggleMenu(false)));

    /* ── 4. Scroll-reveal (IntersectionObserver) ────────────── */
    const revealEls = document.querySelectorAll('.reveal, .reveal-left, .reveal-right, .skill-card');
    const observer  = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
          /* Trigger ring animation for skill cards */
          if (entry.target.classList.contains('skill-card')) {
            const pct  = parseInt(entry.target.dataset.pct || '0');
            const circ = 2 * Math.PI * 30; /* r=30 */
            const offset = circ - (pct / 100) * circ;
            const ring = entry.target.querySelector('.ring-fill');
            if (ring) ring.style.strokeDashoffset = offset;
          }
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.15 });
    revealEls.forEach(el => observer.observe(el));

    /* ── 5. Active nav link highlight ──────────────────────── */
    const sections = document.querySelectorAll('section[id]');
    const navLinks = document.querySelectorAll('.nav-links a');
    const sectionObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          navLinks.forEach(a => {
            a.style.color = a.getAttribute('href') === '#' + entry.target.id
              ? 'var(--gold)'
              : '';
          });
        }
      });
    }, { rootMargin: '-40% 0px -55% 0px' });
    sections.forEach(s => sectionObserver.observe(s));

    /* ── 6. Footer year ─────────────────────────────────────── */
    document.getElementById('year').textContent = new Date().getFullYear();